

function showToast(m) {
    var t = document.getElementById('toast');
    t.textContent = m; t.classList.add('show');
    setTimeout(function(){ t.classList.remove('show'); }, 2800);
}

function escHtml(s) {
    if (!s) return '';
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

function avatarCell(avatarUrl, initial) {
    if (avatarUrl) {
        var img = document.createElement('img');
        img.src = avatarUrl;
        img.style.cssText = 'width:32px;height:32px;border-radius:50%;object-fit:cover;background:#e5e7eb';
        img.onerror = function() {
            var d = document.createElement('div');
            d.className = 'avatar-fb';
            d.textContent = initial || '?';
            img.parentNode.replaceChild(d, img);
        };
        return img.outerHTML;
    }
    return '<div class="avatar-fb">' + escHtml(initial || '?') + '</div>';
}

function srcLinkCell(title, url) {
    if (!title || !url) return '<td class="src-cell">-</td>';
    var t = escHtml(title);
    var disp = t.length > 24 ? t.substring(0,24)+'...' : t;
    return '<td class="src-cell"><a href="' + escHtml(url) + '" target="_blank" title="' + t + '">' + disp + '</a></td>';
}

function b64ToJson(b64) {
    var binary = atob(b64);
    var bytes = new Uint8Array(binary.length);
    for (var i = 0; i < binary.length; i++) { bytes[i] = binary.charCodeAt(i); }
    return JSON.parse(new TextDecoder('utf-8').decode(bytes));
}



(function() {
var DATA_bili = b64ToJson("");
window.PAGE_bili = 1;
var PFOLDER_bili = "C:\\Users\\HI\\.claude\\skills\\media-crawler-easy\\MediaCrawler\\data\\bili\\csv";

window['openFolder_bili'] = function() {
    var a = document.createElement('a');
    a.href = "file:///" + PFOLDER_bili.replace(/\\\\/g, "/");
    a.target = "_blank"; a.click();
    setTimeout(function(){ showToast('若未弹出，请手动打开文件夹'); }, 600);
};
window['copyPath_bili'] = function() {
    var pp = PFOLDER_bili.replace(/\\\\/g, '\\');
    if (navigator.clipboard) {
        navigator.clipboard.writeText(pp).then(function(){ showToast('已复制路径到剪贴板'); });
    } else { prompt('复制此路径:', pp); }
};

window['renderTable_bili'] = function() {
    var q = (document.getElementById('search-bili').value || '').toLowerCase().trim();
    var sort = document.getElementById('sort-bili').value;
    var ps = parseInt(document.getElementById('psize-bili').value) || 20;
    var data = DATA_bili.slice();

    if (q) {
        data = data.filter(function(c) {
            return (c["content"]||'').toLowerCase().indexOf(q) >= 0 ||
                   (c["nickname"]||'').toLowerCase().indexOf(q) >= 0 ||
                   (c._content_title||'').toLowerCase().indexOf(q) >= 0;
        });
    }

    if (sort === 'like') {
        data.sort(function(a,b){ return (parseInt(b["like_count"])||0) - (parseInt(a["like_count"])||0); });
    } else if (sort === 'time') {
        data.sort(function(a,b){ return (parseInt(b["create_time"])||0) - (parseInt(a["create_time"])||0); });
    }

    var tp = Math.ceil(data.length / ps) || 1;
    if (window.PAGE_bili > tp) window.PAGE_bili = tp;
    var start = (window.PAGE_bili - 1) * ps;
    var pd = data.slice(start, start + ps);

    var rows = [];
    for (var i = 0; i < pd.length; i++) {
        var c = pd[i];
        var nick = c["nickname"] || '?';
        var text = escHtml(c["content"] || '');
        var likes = parseInt(c["like_count"]) || 0;
        var ts = parseInt(c["create_time"]) || 0;
        var tstr = ts ? new Date(ts*1000).toLocaleString('zh-CN') : '-';
        var av = avatarCell(c["avatar"] || '', nick.charAt(0));
        var sl = srcLinkCell(c._content_title || '', c._content_url || '');

        rows.push('<tr>' +
            '<td class="avatar-cell">' + av + '</td>' +
            '<td style="white-space:nowrap;font-size:13px">' + escHtml(nick) + '</td>' +
            '<td class="text-cell">' + text + '</td>' +
            sl +
            '<td style="text-align:right;white-space:nowrap">' + (likes||'') + '</td>' +
            '<td style="white-space:nowrap;font-size:12px;color:var(--text2)">' + tstr + '</td>' +
            '</tr>');
    }

    document.getElementById('tbody-bili').innerHTML = rows.join('') ||
        '<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--text2)">没有匹配的评论</td></tr>';

    var h = '<button '+(window.PAGE_bili===1?'disabled':'')+' onclick="window.PAGE_bili=window.PAGE_bili-1;renderTable_bili()">上一页</button>';
    var ms = 7;
    var ps2 = Math.max(1, window.PAGE_bili - Math.floor(ms/2));
    var pe = Math.min(tp, ps2 + ms - 1);
    if (pe - ps2 < ms - 1) ps2 = Math.max(1, pe - ms + 1);
    for (var j = ps2; j <= pe; j++) {
        h += '<button class="'+(j===window.PAGE_bili?'pg-active':'')+'" onclick="window.PAGE_bili='+j+';renderTable_bili()">'+j+'</button>';
    }
    h += '<button '+(window.PAGE_bili===tp?'disabled':'')+' onclick="window.PAGE_bili=window.PAGE_bili+1;renderTable_bili()">下一页</button>';
    h += '<span class="pg-info">共 '+data.length+' 条 / '+tp+' 页</span>';
    document.getElementById('pgn-bili').innerHTML = h;
};

renderTable_bili();
})();


